{"content":"package cli

import (
	"errors"
	"reflect"
	"testing"
)

func mustCfg(t *testing.T, args []string) Config {
	t.Helper()
	c, err := Parse(args)
	if err != nil {
		t.Fatalf("Parse(%v) error: %v", args, err)
	}
	return c
}

func TestSpec(t *testing.T) {
	cases := []struct {
		args   []string
		want   Config
	}{
		{[]string{"-v"}, Config{Verbose: true, Count: 1, Output: "-"}},
		{[]string{"-v", "-v"}, Config{Verbose: true, Count: 1, Output: "-"}},
		{[]string{"-vv"}, Config{Verbose: true, Count: 1, Output: "-"}},
		{[]string{"--verbose"}, Config{Verbose: true, Count: 1, Output: "-"}},
		{[]string{"-n", "3"}, Config{Count: 3, Output: "-"}},
		{[]string{"-n=3"}, Config{Count: 3, Output: "-"}},
		{[]string{"--count", "0"}, Config{Count: 0, Output: "-"}},
		{[]string{"--count=5"}, Config{Count: 5, Output: "-"}},
		{[]string{"-o", "f.txt"}, Config{Count: 1, Output: "f.txt"}},
		{[]string{"-o=f.txt"}, Config{Count: 1, Output: "f.txt"}},
		{[]string{"--output", "g"}, Config{Count: 1, Output: "g"}},
		{[]string{"--output=g"}, Config{Count: 1, Output: "g"}},
		{[]string{"--tag", "a", "--tag=b"}, Config{Count: 1, Output: "-", Tags: []string{"a", "b"}}},
		{[]string{"x", "y"}, Config{Count: 1, Output: "-", Args: []string{"x", "y"}}},
		{[]string{"-"}, Config{Count: 1, Output: "-", Args: []string{"-"}}},
		{[]string{"a", "--", "-b"}, Config{Count: 1, Output: "-", Args: []string{"a", "-b"}}},
		{[]string{"--", "-v", "x"}, Config{Count: 1, Output: "-", Args: []string{"-v", "x"}}},
		{[]string{"-v", "-n", "2", "-o", "out", "pos"}, Config{Verbose: true, Count: 2, Output: "out", Args: []string{"pos"}}},
		{nil, Config{Count: 1, Output: "-"}},
	}
	for _, tc := range cases {
		got := mustCfg(t, tc.args)
		if got.Count != tc.want.Count || got.Output != tc.want.Output || got.Verbose != tc.want.Verbose ||
			!reflect.DeepEqual(got.Tags, tc.want.Tags) || !reflect.DeepEqual(got.Args, tc.want.Args) {
			t.Errorf("Parse(%v) = %+v, want %+v", tc.args, got, tc.want)
		}
	}
}

func TestErrors(t *testing.T) {
	bad := [][]string{
		{"-n"},
		{"-n", "abc"},
		{"-n", "-1"},
		{"-n=xyz"},
		{"--count"},
		{"--count", "1.5"},
		{"--count=-2"},
		{"-o"},
		{"--output"},
		{"--tag"},
		{"--nope"},
		{"-z"},
		{"--tag=a", "--bogus"},
	}
	for _, args := range bad {
		_, err := Parse(args)
		if err == nil {
			t.Errorf("Parse(%v) succeeded, want error", args)
			continue
		}
		if !errors.Is(err, ErrUsage) {
			t.Errorf("Parse(%v) error %v does not wrap ErrUsage", args, err)
		}
	}
}
